// src/App.js
import React from "react";
import { BrowserRouter as Router, Routes, Route } from "react-router-dom";
import Navbar from "./components/Navbar";
import Home from "./pages/Home"; // Asegúrate de que el componente Home esté en esta ruta
import Cursos from "./pages/Cursos";
import CursoDetalle from "./pages/CursoDetalle";
import Inscripcion from "./pages/Inscripcion";
// Asegúrate de importar correctamente todos los componentes si los vas a usar en las rutas

const App = () => {
  return (
    <Router>
      <Navbar />
      <Routes>
        <Route path="/" element={<Home />} /> {/* Cambié <Inicio /> por <Home /> */}
        <Route path="/cursos" element={<Cursos />} />
        <Route path="/curso-detalle" element={<CursoDetalle />} /> {/* Añadí ruta para curso detalle */}
        <Route path="/inscripcion" element={<Inscripcion />} />
      </Routes>
    </Router>
  );
};

export default App;
